                node.message_measure = &TableNodeMessageMeasureThunk<Ctx, TreeNode>;
                node.message_save = &TableNodeMessageSaveThunk<Ctx, TreeNode>;
                if ( !TableNumberingAppend( numbering, node ) ) { return false; }
