            case 0xb97e90a3784c431dull: return TreeNodeMeasureBodyRetain( c, nn, ii, *(const TreeNode *) node, rt, at ); // TreeNode
            case 0x9d8b8aa2b404c2c8ull: return SettingsMeasureBodyRetain( ii, *(const Settings *) node, rt, at ); // Settings
            default: break;
