            case 0xd6458a3eef83d457ull: return MarkerMeasureBodyRetain( c, nn, ii, *(const Marker *) node, rt, at ); // Marker
            case 0xf60ec899a5a69fa9ull: return ListNodeMeasureBodyRetain( c, nn, ii, *(const ListNode *) node, rt, at ); // ListNode
            default: break;
